usSuit == 4)\r\n                            counter4++;\r\n                        else if (rankPlusSuit == 3)\r\n                            counter3++;\r\n                        else if (rankPlusSuit == 2)\r\n                            counter2++;\r\n                        else\r\n                            Debug.WriteLine("should not happen");\r\n\r\n                        counter++;\r\n                    }\r\n                }\r\n            }\r\n\r\n        }\r\n        Debug.WriteLine($"{counter8} {counter7} {counter6} {counter5} {counter4} {counter3} {counter2} {counter8 + counter7 + counter6 + counter5 + counter4 + counter3 + counter2} {counter}");\r\n        return counter;
