SET CLIENT_ENCODING TO 'utf8';

CREATE TABLE badges (
    id integer NOT NULL,
    userid integer,
    name character varying(50),
    date timestamp without time zone,
    class smallint,
    tagbased boolean
);

CREATE TABLE comments (
    id integer NOT NULL,
    postid integer,
    score integer,
    text character varying(600),
    creationdate timestamp without time zone,
    userdisplayname character varying(30),
    userid integer
);

CREATE TABLE inventory (
    id integer NOT NULL,
    name character varying(50),
    quantity integer
);

CREATE SEQUENCE inventory_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE posthistory (
    id integer NOT NULL,
    posthistorytypeid smallint,
    postid integer,
    revisionguid uuid,
    creationdate timestamp without time zone,
    userid integer,
    userdisplayname character varying(40),
    comment character varying(400),
    text character varying
);

CREATE TABLE postlinks (
    id integer NOT NULL,
    creationdate timestamp without time zone,
    postid integer,
    relatedpostid integer,
    linktypeid smallint
);

CREATE TABLE posts (
    id integer NOT NULL,
    posttypeid smallint,
    acceptedanswerid integer,
    parentid integer,
    creationdate timestamp without time zone,
    deletiondate timestamp without time zone,
    score integer,
    viewcount integer,
    body character varying,
    owneruserid integer,
    ownerdisplayname character varying(40),
    lasteditoruserid integer,
    lasteditordisplayname character varying(40),
    lasteditdate timestamp without time zone,
    lastactivitydate timestamp without time zone,
    title character varying(250),
    tags character varying(250),
    answercount integer,
    commentcount integer,
    favoritecount integer,
    closeddate timestamp without time zone,
    communityowneddate timestamp without time zone
);

CREATE TABLE tags (
    id integer NOT NULL,
    tagname character varying(35),
    count integer,
    excerptpostid integer,
    wikipostid integer
);

CREATE TABLE users (
    id integer NOT NULL,
    reputation integer,
    creationdate timestamp without time zone,
    displayname character varying(40),
    lastaccessdate timestamp without time zone,
    websiteurl character varying(200),
    location character varying(100),
    aboutme character varying,
    views integer,
    upvotes integer,
    downvotes integer,
    profileimageurl character varying(200),
    emailhash character varying(32),
    age integer,
    accountid integer
);

CREATE TABLE votes (
    id integer NOT NULL,
    postid integer,
    votetypeid smallint,
    userid integer,
    creationdate timestamp without time zone,
    bountyamount integer
);


